        document.addEventListener('deviceready', function () {
            // Override click events for cordova
            // Sets up external http(s) and mailto links so that the click causes the
            // system action in a separate window (browser or email client).
            // This is done with the InAppBrowser.open() with a target of _system.
            // Relative links to other pages in the app still use the mobile app viewport.
            // All other href values are set up to do nothing.
            document.addEventListener('click', function (event) {
                const path = event.composedPath();
                const anchor = path.find(element => element.tagName === 'A');
                if (!anchor) return;

                const href = (anchor.getAttribute('href') || '').trim().toLowerCase();
                if (!href) {
                    event.preventDefault();
                    return;
                }

                // Internal anchors (alpha-only - already lowercase)
                if (/^[a-z]+$/.test(href)) {
                    return;
                }

                // Send external links to InAppBrowser
                if (href.startsWith('http://') ||
                    href.startsWith('https://') ||
                    href.startsWith('mailto:')) {

                    event.preventDefault();
                    cordova.InAppBrowser.open(href, '_system', 'location=yes');
                    return;
                }

                // Block everything else
                event.preventDefault();
            }, true); // dispatch event to listener first
        });
     

    

     
 

 
     
     
         
